import json
import re
from typing import Any, Dict, List, Optional, Tuple

MEMORY_RELEVANT_KEYS = {
    "gpu_memory_utilization", "max_num_seqs", "max_model_len", 
    "num_gpu_blocks", "swap_space", "max_tokens_per_prompt", 
    "max_num_batched_tokens", "tensor_parallel_size", "pipeline_parallel_size"
}

def is_memory_relevant(key: str) -> bool:
    return key in MEMORY_RELEVANT_KEYS

def raises_memory(key: str, before: Any, after: Any) -> bool:
    try:
        b = float(before)
        a = float(after)
    except (ValueError, TypeError):
        return False
    if key in ("tensor_parallel_size", "pipeline_parallel_size"):
        return a < b
    return a > b

def run(dataset: Dict[str, Any]) -> Dict[str, List[Dict[str, Any]]]:
    proposals = []
    refused = []

    records = dataset.get("records", [])
    evidence_list = dataset.get("evidence", [])

    for rec in records:
        rid = rec.get("id")
        if rid is None:
            continue

        trusted_log_lines = []
        config_before = None
        config_after = None
        deploy_id = None

        for ev in evidence_list:
            if ev.get("record_id") != rid:
                continue
            if not ev.get("trusted"):
                continue

            src = ev.get("source")
            data = ev.get("data", {})

            if src == "log":
                lines = data.get("lines", [])
                if isinstance(lines, list):
                    trusted_log_lines.extend(lines)
            elif src == "config_before":
                config_before = data.get("config", {})
            elif src == "config_after":
                config_after = data.get("config", {})
            elif src == "deploy":
                deploy_id = data.get("id")

        oom_pattern = re.compile(r"(CUDA out of memory|OutOfMemoryError)", re.IGNORECASE)
        has_oom = any(oom_pattern.search(line) for line in trusted_log_lines)

        if not has_oom:
            has_trusted_log = len(trusted_log_lines) > 0
            if not has_trusted_log:
                refused.append({"record_id": rid, "code": "insufficient_evidence", "reason": "No trusted log evidence found."})
            else:
                refused.append({"record_id": rid, "code": "not_applicable", "reason": "No GPU/CUDA OOM signature in trusted logs."})
            continue

        if config_before is None or config_after is None:
            refused.append({"record_id": rid, "code": "insufficient_evidence", "reason": "Missing trusted config_before or config_after evidence."})
            continue

        if deploy_id is None:
            refused.append({"record_id": rid, "code": "insufficient_evidence", "reason": "Missing trusted deploy evidence."})
            continue

        before_keys = set(config_before.keys())
        after_keys = set(config_after.keys())
        changed_keys = before_keys.symmetric_difference(after_keys)
        changed_keys.update(k for k in before_keys if k in after_keys and config_before[k] != config_after[k])

        mem_relevant_changed = [k for k in changed_keys if is_memory_relevant(k)]

        if len(mem_relevant_changed) == 0:
            refused.append({"record_id": rid, "code": "not_applicable", "reason": "No memory-relevant config keys changed."})
            continue

        if len(mem_relevant_changed) > 1:
            refused.append({"record_id": rid, "code": "requires_review", "reason": "Multiple memory-relevant config keys changed."})
            continue

        key = mem_relevant_changed[0]
        before_val = config_before.get(key)
        after_val = config_after.get(key)

        if before_val is None or after_val is None:
            refused.append({"record_id": rid, "code": "insufficient_evidence", "reason": f"Missing value for key {key} in config."})
            continue

        if not raises_memory(key, before_val, after_val):
            refused.append({"record_id": rid, "code": "not_applicable", "reason": f"Change in {key} does not raise memory demand."})
            continue

        proposals.append({
            "record_id": rid,
            "field": key,
            "value": before_val,
            "action_type": "revert_config",
            "reason": f"class=serving_config_regression;key={key};from={after_val};to={before_val};deploy={deploy_id}"
        })

    return {"proposals": proposals, "refused": refused}
